```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitLoss; // positive value for profit, negative for loss

  Transaction(this.coinName, this.datetime, this.profitLoss);
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  Map<String, double> coinStats = {};

  for (var transaction in transactions) {
    if (coinStats.containsKey(transaction.coinName)) {
      coinStats[transaction.coinName] += transaction.profitLoss;
    } else {
      coinStats[transaction.coinName] = transaction.profitLoss;
    }
  }

  return coinStats;
}

List<Transaction> getTopCoins({required Map<String, double> coinStats, int numTop = 3}) {
  List<Transaction> topCoins = [];

  coinStats.forEach((coinName, avgProfitLoss) {
    topCoins.add(Transaction(coinName, DateTime.now(), avgProfitLoss));
  });

  topCoins.sort((a, b) => b.profitLoss.compareTo(a.profitLoss));

  return topCoins.take(numTop).toList();
}

