2. **Configure CORS:**
Create a new file named `cors.js` in the root directory of your Node.js server (usually, it's located at `server.js`). Add the following code to the file:

```javascript
const cors = require('cors');

module.exports = function(req, res, next) {
  res.setHeader('Access-Control-Allow-Origin', '*'); // Replace with your allowed domains if needed
  res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE');
  res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Requested-With, Location, Authorization');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Accept, X-Requested-With, Authorization');

  next();
};
```

Replace `'*'` in `Access-Control-Allow-Origin` with the domain name or IP address of your Next.js application.

3. **Enable CORS middleware:**
Add the following lines at the beginning of your `server.js` or `app.js` file to enable the CORS middleware:

