public class RestServiceWrapper<T> where T : new()
{
    private readonly string _baseUrl;
    private readonly HttpClient _httpClient;
    private string _authToken;

    public RestServiceWrapper(string baseUrl)
    {
        _baseUrl = baseUrl;
        _httpClient = new HttpClient();
    }

    // Setter method for authentication token
    public void SetAuthToken(string token)
    {
        _authToken = token;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
    }

    // Helper method for sending GET request and deserializing JSON response
    public async Task<T> GetAsync(string endpoint)
    {
        var responseString = await _httpClient.GetAsync($"{_baseUrl}/{endpoint}");
        responseString.EnsureSuccessStatusCode();
        var responseJson = await responseString.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(responseJson);
    }

    // Helper method for sending POST request with JSON body and deserializing JSON response
    public async Task<T> PostAsync(string endpoint, object data)
    {
        var jsonData = JsonConvert.SerializeObject(data);
