```javascript
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import * as JWT from 'jsonwebtoken';
import * as dotenv from 'dotenv';
import { Permission } from './permission.entity';
import { UserRolesEnum } from './user-roles.enum';
import { AuthGuard } from './auth.guard';
import { Roles } from './roles.decorator';
import { GqlContextType } from './graphql.types';

// Load environment variables
dotenv.config();

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  // Set up JWT middleware
  app.useGlobalGuards(new AuthGuard());

  app.use((req, res, next) => {
    const token = req.headers['x-access-token'];
    if (!token) return res.status(403).send('Access Denied');

    JWT.verify(token, process.env.JWT_SECRET, (err, decoded) => {
      if (err) return res.status(500).send('Invalid Token');
      req.user = decoded;
      next();
    });
  });

  // Set up access control decorator
  app.useGlobalDecorators(Roles());

  // Set up routes and start server
  await app.listen(3000, () => console.log('Server started on port 3000'));
}

bootstrap();

