    const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(placeName)}&key=${apiKey}`;
    const response = UrlFetchApp.fetch(url);
    const json = JSON.parse(response.getContentText());

    if (json.status === "OK") {
      // Extract latitude and longitude from response
      const latitude = json.results[0].geometry.location.lat;
      const longitude = json.results[0].geometry.location.lng;

      // Store results in columns C and D
      sheet.getRange(i, 3).setValue(latitude);
      sheet.getRange(i, 4).setValue(longitude);
    } else {
      Logger.log(`Error geocoding ${placeName}: ${json.error_message}`);
    }
  }
}
```

