```javascript
import { useState } from 'react';

const conversionRates = {
  celsiusToFahrenheit: (celsius) => Math.round(celsius * 9 / 5 + 32),
  fahrenheitToCelsius: (fahrenheit) => Math.round((fahrenheit - 32) * 5 / 9),
};

export const useTemperatureConverter = (initialValue, unit) => {
  const [temperature, setTemperature] = useState(initialValue);
  const [currentUnit, setCurrentUnit] = useState(unit);

  const handleConvert = () => {
    const newTemperature = conversionRates[`${currentUnit}To${currentUnit === 'celsius' ? 'fahrenheit' : 'celsius'}`](temperature);
    setTemperature(newTemperature);
  };

  return { temperature, currentUnit, setCurrentUnit, handleConvert };
};
```

Now, we can create a functional component called `TemperatureConverter` that uses our custom hook:

```javascript
import React from 'react';
import { useTemperatureConverter } from './useTemperatureConverter';

const TemperatureConverter = () => {
  const { temperature, currentUnit, setCurrentUnit, handleConvert } = useTemperatureConverter(20, 'celsius'); // initial value and unit

  return (
    <div>
      <h1>{temperature}</h1>
      <button onClick={handleConvert}>Convert</button>
      <select value={currentUnit} onChange={(e) => setCurrentUnit(e.target.value)}>
        <option value="celsius">Celsius</option>
        <option value="fahrenheit">Fahrenheit</option>
      </select>
    </div>
  );
};

export default TemperatureConverter;
