2. Create a method in a helper class or controller to extract the username from the JWT token.

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.AspNetCore.Mvc;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Handling the JWT error
        var handler = new JwtSecurityTokenHandler();

        // Validate and parse the token
        JwtSecurityToken securityToken;
        if (!TryParseJwt(jwtToken, out securityToken))
            throw new ArgumentException("Invalid JWT format.");

        // Retrieve the username from the claims
        return securityToken.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
    }
    catch (Exception ex)
    {
        // Handle exceptions accordingly
        throw new BadRequestObjectResult($"Error retrieving username: {ex.Message}");
    }

    static bool TryParseJwt(string jwtToken, out JwtSecurityToken token)
    {
        token = null;

        try
        {
            token = handler.ReadJwtToken(jwtToken);
            return true;
        }
        catch
        {
            return false;
        }
    }
}
```

