$week_start = date('Y-m-d', strtotime('last Monday')); // Get last Monday of current week
$week_end = date('Y-m-d', strtotime('next Sunday')); // Get next Sunday of current week

// Build SQL query
$sql = "SELECT customers.name, COUNT(*) as purchase_count 
        FROM transactions 
        JOIN products ON transactions.product_id = products.id 
        JOIN customers ON transactions.customer_id = customers.id 
        WHERE products.name = '$product' AND transactions.date BETWEEN '$week_start' AND '$week_end' 
        GROUP BY customers.id 
        HAVING purchase_count >= 3";

// Execute query
$result = $conn->query($sql);

