  } catch (error) {
    console.error('Error opening camera:', error);
  }
}
```

2. CloseCamera: This method stops the camera stream.

```javascript
function closeCamera(stream) {
  if (stream.getVideoTracks().length > 0) {
    const videoTrack = stream.getVideoTracks()[0];
