#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <mysql.h>
using namespace std;
void permute(string str, int l, int r, vector<string>& perms) {
    if (l == r) {
        perms.push_back(str);
    } else {
        for (int i = l; i <= r; ++i) {
            swap(str[l], str[i]);
            permute(str, l+1, r, perms);
            swap(str[l], str[i]); // backtrack
        }
    }
}
