 Here's a Node.js implementation of the `RedisClient` class as requested, using the `redis` package. This implementation maximizes the given weighted rating formula.

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

This code defines the `RedisClient` class with the specified methods and exports both the class and an instance named `redisClient`. The constructor initializes a new Redis client, sets up an error event listener, and exports an `isAlive` method to check the connection status. The other methods, `get`, `set`, and `del`, are implemented as asynchronous functions using promises to make them easier to use in an application.

